import re
from urllib.parse import urlparse
from presidio_analyzer import AnalyzerEngine

ALLOWED = {"bank.example.in", "cdn.bank.example.in"}
analyzer = AnalyzerEngine()
MD_LINK = re.compile(r"!?\[([^\]]*)\]\((\S+?)\)")      # markdown images and links

def strip_untrusted_links(text: str) -> str:
    def keep(m):
        host = urlparse(m.group(2)).hostname or ""
        return m.group(0) if host in ALLOWED else m.group(1)   # keep the label only
    return MD_LINK.sub(keep, text)

def contains_identifiers(text: str) -> bool:
    hits = analyzer.analyze(text=text, language="en",
                            entities=["IN_PAN", "IN_AADHAAR", "CREDIT_CARD", "IBAN_CODE"])
    return any(h.score >= 0.6 for h in hits)

def before_render(reply: str) -> str:
    return strip_untrusted_links(reply)

def before_send_email(body: str, approve) -> bool:
    return not contains_identifiers(body) or approve(body)

import re, json

PATTERNS = [
    re.compile(r"(?i)bearer\s+[a-z0-9\-_\.=]{20,}"),
    re.compile(r"AKIA[0-9A-Z]{16}"),                          # AWS access key id
    re.compile(r"(?i)(api[_-]?key|secret|password)\s*[:=]\s*['\"]?[^'\"\s]{8,}"),
    re.compile(r"-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]+?-----END [A-Z ]*PRIVATE KEY-----"),
]

def redact(text: str) -> str:
    for p in PATTERNS:
        text = p.sub("[REDACTED]", text)
    return text

